powerpagecomponent.content:
{
  "source": "{% extends 'Layout 1 Column' %}
{% block main %}
<div class="wrapper-body content-wrapper" role="main">
    <div class="container">
        <div class="page-heading">
            {% block title %}
            {% include 'Page Header' %}
            {% endblock %}
        </div>
    </div>
    {% include 'Page Copy' %}
</div>

{% if request.params['contactid'] %}
    {% assign contactid = request.params['contactid'] %}
{% endif %}

{% assign clientid = '' %}
{% if request.params['clientid'] %}
    {% assign clientid = request.params['clientid'] %}
    {% assign account = entities['account'][clientid] %}
    {% assign clientName = account.name %}
    {% assign accountName = account.name %}
{% endif %}
<script type="text/javascript">
    (function() {
        var sessionExpiry = localStorage.getItem('QSsessionExpiry');
        var loggedInContactId = localStorage.getItem('QScontactid');
        var requestedContactId = "{{contactid}}";

        if (!sessionExpiry) {
            window.location.href = '/qssignin';
        } else {
            var expiryDate = new Date(sessionExpiry);
            var now = new Date();
            if (now >= expiryDate || loggedInContactId !== requestedContactId) {
                window.location.href = '/qssignin';
            } else {
                document.addEventListener('DOMContentLoaded', function() {
                    var content = document.querySelector('.content-wrapper');
                    if (content) {
                        content.style.display = 'block';
                    }
                });
            }
        }
    })();

    function isSessionValid() {
        var sessionExpiry = localStorage.getItem('QSsessionExpiry');
        if (!sessionExpiry) {
            return false;
        }
        var expiryDate = new Date(sessionExpiry);
        // console.log("Session expiryDate ", expiryDate);
        var now = new Date();
        return now < expiryDate;
    }

    if (isSessionValid()) {
        var contactid = localStorage.getItem('QScontactid');
        var clientid = localStorage.getItem('QSclientid');

        console.log('clientid', clientid)

        $('li a').each(function () {
            var currentHref = $(this).attr('href');
            if (currentHref) {
                var separator = currentHref.includes('?') ? '&' : '?';
                var newHref = `${currentHref}${separator}contactid=${contactid}&clientid=${clientid}`;
                $(this).attr('href', newHref);
            }
        });
    } else {
        window.location.href = '/qssignin';
    }
    localStorage.setItem('QSclientid', '{{ clientid }}');

    $(document).ready(function(){
        window.parentClientId = "{{clientid}}";        
        window.parentClientName = "{{clientName}}";
    });
</script>
{% endblock %}"
}
